static _R _playTrackByPath(String method, Map<String, String> params) async {
  final path = params['path'];
  if (path == null || path.isEmpty) return _error('path parameter required');
  final p = DebugHooks.provider as PlaybackController?;
  if (p == null) return _error('provider not registered');

  // Debug/automation helper: treat the filename as the metadata source
  // (mirrors DesktopMetadataExtractor) so dot-hero's Artist/Song overlay can
  // be exercised without relying on platform tag support.
  final base = path.split('/').last;
  final dot = base.lastIndexOf('.');
  final withoutExt = dot > 0 ? base.substring(0, dot) : base;

  // First separator from the left.
  final seps = const <String>['-', '–', '−', '—'];
  var sepIndex = -1;
  for (final s in seps) {
    final i = withoutExt.indexOf(s);
    if (i < 0) continue;
    if (sepIndex < 0 || i < sepIndex) sepIndex = i;
  }

  final artistAndTitle = sepIndex < 0
      ? (artist: '', title: withoutExt)
      : (artist: withoutExt.substring(0, sepIndex).trim(),
          title: withoutExt.substring(sepIndex + 1).trim());

  await p.playOneShot(
    AudioTrack(
      path: path,
      title: artistAndTitle.title.isEmpty ? withoutExt : artistAndTitle.title,
      artist: artistAndTitle.artist,
    ),
  );
  return _ok({'ok': true, 'path': path});
}

}

// Keep the in-memory SettingsService notifiers in sync when the agent
// mutates screen/persistence keys directly.
if (key == 'active_screen_id' || key.startsWith('screen_config_')) {
  await SettingsService().loadSettings();
}

return _ok({'set': key, 'value': value, 'type': type});

